import math
from itertools import permutations

def is_square(n):
    if n < 1:
        return False
    sqrt_n = int(math.sqrt(n))
    return sqrt_n * sqrt_n == n

def check_coolness(n):
    # Check the necessary condition first (already done by W2, but good practice)
    s_n = n * (n + 1) // 2
    if is_square(s_n):
        return False # Not cool

    # Backtracking search using permutations for small N (N<=10 perhaps, brute force quickly exceeds time limits)
    # Since the task is up to N=30, simple permutations will time out very quickly (30! is huge).
    # We must rely on the structured backtracking search.

    # A dedicated recursive function is better than itertools.permutations for performance

    def backtrack(current_prefix, used_mask, current_sum):
        if len(current_prefix) == n:
            return True

        # Try every unused number
        for i in range(n):
            if not (used_mask & (1 << i)): # i corresponds to number i+1
                x = i + 1
                new_sum = current_sum + x

                if not is_square(new_sum):
                    # Move forward
                    if backtrack(current_prefix + [x], used_mask | (1 << i), new_sum):
                        return True
        return False

    # Start search
    return backtrack([], 0, 0)

