def get_pell_solutions(m):
    # (3 + sqrt(8))^m = y + k*sqrt(8)
    # We are solving y^2 - 8k^2 = 1
    # n = (y - 1) / 2

    if m == 1:
        return 3, 1
    if m == 2:
        return 17, 6

    # Use recurrence relations:
    # y_m = 6*y_{m-1} - y_{m-2}
    # k_m = 6*k_{m-1} - k_{m-2}

    y_prev2, k_prev2 = 3, 1
    y_prev1, k_prev1 = 17, 6

    for _ in range(3, m + 1):
        y_current = 6 * y_prev1 - y_prev2
        k_current = 6 * k_prev1 - k_prev2
        y_prev2, k_prev2 = y_prev1, k_prev1
        y_prev1, k_prev1 = y_current, k_current

    return y_prev1, k_prev1

def calculate_nm(m):
    y, k = get_pell_solutions(m)
    return (y - 1) // 2

